const now = new Date();
const end = now.toISOString().slice(0, 10);
const start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
return [{ json: { startDate: start, endDate: end } }];

const resp = $input.first().json;
const posts = resp.posts || [];

function extractHashtags(content) {
  const matches = (content || '').match(/#\w+/g) || [];
  return [...new Set(matches.map(t => t.toLowerCase()))];
}

const rows = posts.map(p => {
  const a = p.analytics || {};
  const views = a.views || 0;
  const likes = a.likes || 0;
  const comments = a.comments || 0;
  const shares = a.shares || 0;
  const engagement = views > 0 ? (likes + comments + shares) / views : 0;
  const platformEntry = (p.platforms || []).find(pl => pl.platform === 'tiktok') || {};
  return {
    platform_post_id: platformEntry.platformPostId || p._id,
    content_snippet: (p.content || '').slice(0, 200),
    hashtags: extractHashtags(p.content),
    media_type: p.mediaType || 'unknown',
    published_at: p.publishedAt || null,
    views, likes, comments, shares,
    engagement_rate: Math.round(engagement * 10000) / 10000,
    post_url: platformEntry.platformPostUrl || p.platformPostUrl || '',
    last_synced_at: a.lastUpdated || null,
    run_date: new Date().toISOString().slice(0, 10)
  };
});

rows.sort((a, b) => b.views - a.views);

const totalPosts = rows.length;
const totalViews = rows.reduce((s, r) => s + r.views, 0);
const avgViews = totalPosts ? totalViews / totalPosts : 0;
const breakoutThreshold = avgViews * 3;
const breakouts = rows.filter(r => r.views >= breakoutThreshold && r.views > 0 && avgViews > 0);

const byFormat = {};
for (const r of rows) {
  byFormat[r.media_type] = byFormat[r.media_type] || { count: 0, totalViews: 0 };
  byFormat[r.media_type].count += 1;
  byFormat[r.media_type].totalViews += r.views;
}

const hashtagStats = {};
for (const r of rows) {
  for (const tag of r.hashtags) {
    hashtagStats[tag] = hashtagStats[tag] || { count: 0, totalViews: 0 };
    hashtagStats[tag].count += 1;
    hashtagStats[tag].totalViews += r.views;
  }
}
const topHashtags = Object.entries(hashtagStats)
  .map(([tag, s]) => ({ tag, count: s.count, avgViews: Math.round(s.totalViews / s.count) }))
  .sort((a, b) => b.avgViews - a.avgViews)
  .slice(0, 8);

return [{ json: { rows, totalPosts, totalViews, avgViews: Math.round(avgViews * 10) / 10, breakouts, byFormat, topHashtags } }];

const data = $input.first().json;
const rows = data.rows;
const today = new Date().toISOString().slice(0, 10);

const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const postRow = (r) => `
  <div style="margin-bottom:14px;padding:10px;border:1px solid #ddd;border-radius:8px">
    <p><strong>${r.views} views</strong> &middot; ${r.likes} likes &middot; ${r.comments} comments &middot; ${r.shares} shares &middot; ${esc(r.media_type)}</p>
    <p>${esc(r.content_snippet)}${r.content_snippet.length >= 200 ? '...' : ''}</p>
    <p><a href="${esc(r.post_url)}">view post</a></p>
  </div>`;

const top5 = rows.slice(0, 5);
const bottom5 = rows.length > 5 ? rows.slice(-5).reverse() : [];

const top5Html = top5.length ? '<h2>Top 5 by views</h2>' + top5.map(postRow).join('') : '<p>No posts in this window.</p>';
const bottom5Html = bottom5.length ? '<h2>Bottom 5 by views</h2>' + bottom5.map(postRow).join('') : '';
const breakoutHtml = data.breakouts.length ? '<h2>Breakouts (3x+ account average)</h2>' + data.breakouts.map(postRow).join('') : '';

const formatRows = Object.entries(data.byFormat)
  .map(([fmt, s]) => `<li><strong>${esc(fmt)}</strong> - ${s.count} post(s), avg ${Math.round(s.totalViews / s.count)} views</li>`)
  .join('');
const formatHtml = `<h2>By format</h2><ul>${formatRows}</ul>`;

const hashtagHtml = data.topHashtags.length
  ? '<h2>Top hashtags (by avg views)</h2><ul>' + data.topHashtags.map(h => `<li><strong>${esc(h.tag)}</strong> - avg ${h.avgViews} views over ${h.count} post(s)</li>`).join('') + '</ul>'
  : '';

const html = `<h1>Crawli TikTok performance - ${today}</h1>
  <p>${data.totalPosts} post(s) tracked (last 30 days), ${data.totalViews} total views, ${data.avgViews} avg views/post.</p>
  ${formatHtml}
  ${hashtagHtml}
  ${breakoutHtml}
  ${top5Html}
  ${bottom5Html}`;

return [{ json: {
  html,
  subject: `Crawli TikTok performance (${data.totalPosts} posts, ${data.totalViews} views) - ${today}`,
  rows
} }];
